/* Shared constants for the Phase B / P014 separate-process path, used by the PS4 child
 * (process_p014_child.c), the title-side spawn watcher (native/wine_hardware.c) and the kernelbase hook
 * (generated by tools/build-guest-hw.py). The child joins the title's real wineserver and creates the
 * named object below; the title (a Wine client) opens the same name to confirm the shared namespace. */
#ifndef POP_SEPARATE_H
#define POP_SEPARATE_H

#define POP_SEP_DIR        "/data/orbisdesk/process-p014"
#define POP_SEP_REQUEST    POP_SEP_DIR "/spawn-request"   /* kernelbase writes the app path here */
#define POP_SEP_APP_UID    POP_SEP_DIR "/app-uid.txt"     /* the title's uid (W228: root can't open its 0600 socket) */
#define POP_SEP_CHILD_LOG  POP_SEP_DIR "/child.jsonl"
/* a 0777 AF_UNIX socket the title listens on, so the child can test a cross-process connect without the
 * wineserver's 0700 directory/0600 socket in the way (EACCES diagnosis, 2026-11-12) */
#define POP_SEP_TITLE_PROBE POP_SEP_DIR "/title-probe.sock"
/* The child ELF is bundled in the package at /app0. BUT the watcher runs AFTER the eboot's jailbreak, which
 * escapes the app sandbox (changes rootdir/prison, W228), so /app0 no longer resolves there. From the real
 * root the same file is reachable at its sandbox mount, and /data is always reachable. The watcher tries these
 * in order (pop_loader_spawn.h): /data first, so a child iteration is an FTP upload instead of a reinstall;
 * then the sandbox copy the install placed. */
#define POP_SEP_CHILD_ELF  "/app0/pop-wine-join.elf"      /* pre-jailbreak path (bundled in the package) */
#define POP_SEP_CHILD_ELF_SANDBOX "/mnt/sandbox/ORBW00002_000/app0/pop-wine-join.elf"  /* real-root path post-escape */
#define POP_SEP_CHILD_ELF_DATA    "/data/orbisdesk/pop-wine-join.elf"                  /* FTP-uploadable fallback */
#define POP_SEP_PREFIX     "/data/wine-prefix"            /* the title's WINEPREFIX */
/* Absolute object path used verbatim on BOTH sides: the slim client creates it, the title opens it with
 * NtOpenMutant. \KernelObjects is a permanent directory directly under root (server init_directories), so it
 * is session-independent -- it avoids the per-session \BaseNamedObjects symlink mismatch that a bare Win32
 * name would hit. Proven reachable cross-process in the host B.0 test. */
#define POP_SEP_OBJECT_A   "\\KernelObjects\\OrbisSeparateJoin"
#define POP_SEP_OBJECT_W   L"\\KernelObjects\\OrbisSeparateJoin"
#define POP_SEP_HOLD_SECONDS 25

/* Phase C / P015: the child's window in the title's desktop (explorer /desktop=shell in WinSta0), its pixels
 * streamed to the title over POP_SEP_SURFACE, composited by the sink at the window's desktop rectangle. */
#define POP_SEP_SURFACE    POP_SEP_DIR "/surface.sock"
#define POP_SEP_WINSTA     "WinSta0"
#define POP_SEP_DESKTOP    "shell"
#define POP_SEP_WIN_X 400
#define POP_SEP_WIN_Y 180
#define POP_SEP_WIN_W 480
#define POP_SEP_WIN_H 300
#define POP_SEP_WINDOW_SECONDS 240
#define POP_SEP_FRAME_MAGIC 0x50455350u   /* "PSEP" */
#include <stdint.h>
struct pop_sep_frame {           /* one frame on the surface socket, followed by w*h BGRA pixels */
    uint32_t magic;
    int32_t  x, y, w, h;         /* the window's desktop rectangle */
    uint32_t frame, window, clicks;
};

#endif
